package com.shazwan.idash;
import android.app.*;import android.content.*;import android.graphics.Rect;import android.media.AudioManager;import android.os.*;import android.provider.Settings;import android.view.*;import android.widget.*;import java.io.*;
/** Disposable emulator only: restores brightness/volume and resets the temporary app-op. */
public class SettingsChecks extends Instrumentation {
 int count;LauncherActivity a;AudioManager audio;int oldVolume=-1,oldBrightness,oldMode;boolean brightnessGranted;
 void check(boolean ok,String why){if(!ok)throw new AssertionError(why);count++;}
 void ui(Runnable work){final Throwable[] error={null};runOnMainSync(()->{try{work.run();}catch(Throwable e){error[0]=e;}});waitForIdleSync();if(error[0]!=null)throw new AssertionError(error[0]);}
 View find(View root,String name){if(name.contentEquals(root.getContentDescription()==null?"":root.getContentDescription()))return root;if(root instanceof ViewGroup){ViewGroup g=(ViewGroup)root;for(int i=0;i<g.getChildCount();i++){View match=find(g.getChildAt(i),name);if(match!=null)return match;}}return null;}
 void tap(String name){ui(()->{View v=find(a.stage,name);check(v!=null,"exists: "+name);v.performClick();});}
 void shell(String cmd)throws Exception{try(ParcelFileDescriptor fd=getUiAutomation().executeShellCommand(cmd);InputStream in=new FileInputStream(fd.getFileDescriptor())){byte[] bytes=new byte[1024];while(in.read(bytes)!=-1){}}}
 void touch(SeekBar bar,float fraction){float x=bar instanceof CapsuleSlider?bar.getWidth()/2f:bar.getWidth()*fraction,y=bar instanceof CapsuleSlider?bar.getHeight()*(1-fraction):bar.getHeight()/2f;long time=SystemClock.uptimeMillis();MotionEvent down=MotionEvent.obtain(time,time,0,x,y,0),up=MotionEvent.obtain(time,time+30,1,x,y,0);bar.dispatchTouchEvent(down);bar.dispatchTouchEvent(up);down.recycle();up.recycle();}
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle result=new Bundle();int outcome=Activity.RESULT_CANCELED;try{
  a=(LauncherActivity)startActivitySync(new Intent(getTargetContext(),LauncherActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();long end=SystemClock.elapsedRealtime()+20000;while(!a.loaded&&SystemClock.elapsedRealtime()<end)Thread.sleep(100);
  ui(()->{a.page="home";a.panelVisible=false;a.prefs.edit().putInt("dock_size",0).apply();a.render();});tap("Settings");ui(()->{check("settings".equals(a.page),"dock opens iDash settings");for(String section:new String[]{"Appearance","Home & Dock","Prayer Times","Panel","About"})check(find(a.stage,"Settings: "+section)!=null,"settings category "+section);});
  tap("Settings: Appearance");final DashSettings screen=new DashSettings(a);final int original=a.prefs.getInt("glass_style",0);
  ui(screen::preview);ui(()->{Spinner picker=(Spinner)find(screen.previewDialog.getWindow().getDecorView(),"Preview material");picker.setSelection((original+1)%3);});ui(()->{check(a.prefs.getInt("glass_style",0)==original,"draft preview does not save");screen.previewDialog.getButton(AlertDialog.BUTTON_NEGATIVE).performClick();});ui(()->check(a.prefs.getInt("glass_style",0)==original,"Cancel preserves original appearance"));
  ui(screen::preview);ui(()->((Spinner)find(screen.previewDialog.getWindow().getDecorView(),"Preview material")).setSelection((original+1)%3));ui(()->screen.previewDialog.getButton(AlertDialog.BUTTON_POSITIVE).performClick());ui(()->{check(a.prefs.getInt("glass_style",0)==(original+1)%3,"Apply saves preview");a.prefs.edit().putInt("glass_style",original).apply();new DashSettings(a).open("Home & Dock");});
  ui(()->((Switch)find(a.stage,"Setting calendar")).setChecked(false));ui(()->{check(!a.prefs.getBoolean("calendar",true),"widget toggle persists");a.page="home";a.render();check(find(a.stage,"Calendar widget")==null,"widget setting affects dashboard");a.prefs.edit().putBoolean("calendar",true).putInt("dock_size",1).apply();a.render();});ui(()->check(find(a.stage,"Favorite Files").getHeight()>=a.dp(68),"comfort dock has larger touch height"));ui(()->{a.prefs.edit().putInt("dock_size",0).putBoolean("prayer_countdown",false).apply();a.render();check(a.jakimNext.getVisibility()==View.GONE,"countdown setting affects dashboard");a.prefs.edit().putBoolean("prayer_countdown",true).apply();new DashSettings(a).open("Panel");check(a.nativePanel==null&&a.webPanel==null&&a.fmPanel==null,"panel settings do not auto-start a player or tuner");});
  shell("appops set com.shazwan.idash WRITE_SETTINGS deny");ui(a::controlCenter);final QuickControls controls=a.quickControls;ui(()->{controls.refresh();check(!controls.brightness.isEnabled(),"brightness disabled without access");check(!controls.wifi.getText().toString().isEmpty()&&!controls.bluetooth.getText().toString().isEmpty(),"wireless status or unavailable state shown");check(find(controls.dialog.getWindow().getDecorView(),"Brightness access / Display")!=null,"explicit brightness access link present");});
  audio=(AudioManager)a.getSystemService(Context.AUDIO_SERVICE);oldVolume=audio.getStreamVolume(AudioManager.STREAM_MUSIC);ui(()->touch(controls.volume,oldVolume>controls.volume.getMax()/2?.2f:.8f));ui(()->check(audio.getStreamVolume(AudioManager.STREAM_MUSIC)!=oldVolume,"user slider changes actual media volume"));audio.setStreamVolume(AudioManager.STREAM_MUSIC,oldVolume,0);
  oldBrightness=Settings.System.getInt(a.getContentResolver(),Settings.System.SCREEN_BRIGHTNESS,128);oldMode=Settings.System.getInt(a.getContentResolver(),Settings.System.SCREEN_BRIGHTNESS_MODE,0);shell("appops set com.shazwan.idash WRITE_SETTINGS allow");brightnessGranted=true;
  ui(()->{check(Settings.System.canWrite(a),"temporary emulator access granted");Settings.System.putInt(a.getContentResolver(),Settings.System.SCREEN_BRIGHTNESS_MODE,0);controls.refresh();check(controls.brightness.isEnabled(),"manual brightness enabled after access");touch(controls.brightness,oldBrightness>128?.2f:.8f);});ui(()->{check(Settings.System.getInt(a.getContentResolver(),Settings.System.SCREEN_BRIGHTNESS,oldBrightness)!=oldBrightness,"user slider writes actual Android brightness");Settings.System.putInt(a.getContentResolver(),Settings.System.SCREEN_BRIGHTNESS_MODE,1);controls.refresh();check(!controls.brightness.isEnabled(),"automatic brightness is respected");controls.close();check(controls.dialog==null,"Control Center closes cleanly");a.prefs.edit().putInt("panel_mode",0).apply();a.panelVisible=true;new DashSettings(a).open("Panel");a.controlCenter();View openPanel=find(a.quickControls.dialog.getWindow().getDecorView(),"Panel");openPanel.performClick();check("home".equals(a.page)&&a.panelVisible&&a.panelBox!=null,"quick Panel action opens from Settings even with retained panel preference");check(a.webPanel!=null&&a.webPanel.web==null,"quick Panel action still waits for Start");a.panelVisible=false;a.page="home";a.settingsSection="";a.render();});
  result.putString("stream","PASS: "+count+" iDash settings/control assertions\n");outcome=Activity.RESULT_OK;
 }catch(Throwable failure){result.putString("stream","FAIL after "+count+": "+failure+"\n");outcome=Activity.RESULT_CANCELED;}finally{try{if(a!=null&&brightnessGranted){Settings.System.putInt(a.getContentResolver(),Settings.System.SCREEN_BRIGHTNESS,oldBrightness);Settings.System.putInt(a.getContentResolver(),Settings.System.SCREEN_BRIGHTNESS_MODE,oldMode);}if(audio!=null&&oldVolume>=0)audio.setStreamVolume(AudioManager.STREAM_MUSIC,oldVolume,0);shell("appops set com.shazwan.idash WRITE_SETTINGS default");}catch(Exception ignored){}if(a!=null)runOnMainSync(()->a.finish());}finish(outcome,result);}
}
